parameters.jsCode:
// Ningún dato inventado llega al cliente: cada número de la respuesta tiene que
// aparecer en lo que devolvió Django en esta misma ejecución (o en el mensaje del
// cliente o la fecha de hoy). Si habla de su cuenta sin haber consultado, tampoco pasa.
const salida = String($json.output || '');
const pasos = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const consultado = pasos.length > 0;
const fuente = [
  JSON.stringify(pasos.map((p) => p.observation ?? '')),
  String($('Al ser llamado').first().json.texto || ''),
  // Lo que el bot o el equipo ya dijeron en esta conversación: esos mensajes
  // pasaron esta misma verificación (o los escribió una persona) al enviarse.
  JSON.stringify(($('Leer historial').first().json.mensajes || [])
    .filter((m) => m.de !== 'cliente').map((m) => m.texto || '')),
  $now.setZone('America/La_Paz').toFormat('dd/MM/yyyy'),
].join(' ');

const lecturas = (s) => {
  // 1.500,50 / 1,500.50 / 150.00 / 150,5: se aceptan las dos convenciones.
  const c = [s.replace(/,/g, ''), s.replace(/\./g, '').replace(',', '.'), s.replace(',', '.')];
  return c.map(Number).filter(Number.isFinite);
};
const permitidos = new Set();
for (const m of fuente.matchAll(/\d+(?:[.,]\d+)*/g)) for (const n of lecturas(m[0])) permitidos.add(n);

const sinRespaldo = [];
for (const m of salida.matchAll(/\d+(?:[.,]\d+)*/g)) {
  const ns = lecturas(m[0]);
  if (ns.some((n) => permitidos.has(n))) continue;
  // Un conteo chico ("2 avisos") puede no figurar literal; un monto o una velocidad sí.
  const despues = salida.slice(m.index + m[0].length, m.index + m[0].length + 12).toLowerCase();
  const antes = salida.slice(Math.max(0, m.index - 4), m.index).toLowerCase();
  const esMedida = /^\s*(bs|bob|bolivianos?|mbps|%|de (enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre))/.test(despues) || /bs\.?\s*$/.test(antes);
  if (!esMedida && ns.some((n) => Number.isInteger(n) && n >= 0 && n <= 10)) continue;
  sinRespaldo.push(m[0]);
}

const afirmaDeLaCuenta = /(deb[eé]s|tu deuda|tu saldo|al d[ií]a|tienes contratado|tu plan es|est[aá] (activo|suspendido|cortado)|mbps|\bbs\b|vence el|venci[oó] el)/i.test(salida);
const ok = salida.trim() !== '' && sinRespaldo.length === 0 && (consultado || !afirmaDeLaCuenta);

return { json: { ...$json, verificacion: { ok, consultado, sin_respaldo: sinRespaldo.slice(0, 10) } } };
